const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const session_id = Number(input.session_id);
const message_id = Number(input.message_id);
const model_provider = text(input.model_provider || 'openai').toLowerCase();
const model_name = text(input.model_name || 'gpt-5-mini');
const prompt_version = text(input.prompt_version || 'response-composer-final-v2');
const confirm_composition = toBoolean(input.confirm_composition);

const errors = [];

if (!Number.isInteger(session_id) || session_id < 1) {
  errors.push({
    field: 'session_id',
    message: 'session_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!Number.isInteger(message_id) || message_id < 1) {
  errors.push({
    field: 'message_id',
    message: 'message_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!model_provider) {
  errors.push({
    field: 'model_provider',
    message: 'ارائه‌دهنده مدل الزامی است.',
  });
}

if (!model_name) {
  errors.push({
    field: 'model_name',
    message: 'نام مدل الزامی است.',
  });
}

if (!prompt_version) {
  errors.push({
    field: 'prompt_version',
    message: 'نسخه پرامپت الزامی است.',
  });
}

if (confirm_composition !== true) {
  errors.push({
    field: 'confirm_composition',
    message: 'ساخت پاسخ باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    session_id,
    message_id,
    model_provider,
    model_name,
    prompt_version,
    response_started_at_ms: Date.now(),
    confirm_composition,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{ json: $json }];
}

const input = $('Normalize and Validate Response Request').first().json;
const context = $json.response_context || {};
const safety = context.safety_payload || {};
const routing = context.routing_payload || {};
const execution = context.execution_payload || null;
const aiRoute = context.ai_route_output || {};

const deterministicInstruction =
  safety.patient_facing_instruction || null;

const responsePrompt = [
  'PATIENT_MESSAGE:',
  JSON.stringify(context.patient_message || ''),
  '',
  'PATIENT_AND_SESSION:',
  JSON.stringify({
    clinic_name: context.clinic_name,
    patient_name: context.patient_name,
    language: context.language,
    session_status: context.session_status,
    last_intent: context.last_intent,
    pending_action: context.pending_action,
    collected_entities: context.collected_entities || {},
  }),
  '',
  'AI_CLASSIFICATION:',
  JSON.stringify(aiRoute),
  '',
  'SAFETY_DECISION:',
  JSON.stringify(safety),
  '',
  'TOOL_ROUTE:',
  JSON.stringify(routing),
  '',
  'TOOL_EXECUTION_RESULT:',
  JSON.stringify(execution),
  '',
  'DETERMINISTIC_INSTRUCTION:',
  JSON.stringify(deterministicInstruction),
  '',
  'RECENT_MESSAGES:',
  JSON.stringify($json.recent_messages || []),
  '',
  'Return only the structured response required by the output schema.',
].join('\n');

return [{
  json: {
    ...$json,
    deterministic_instruction:
      deterministicInstruction,
    model_provider: input.model_provider,
    model_name: input.model_name,
    prompt_version: input.prompt_version,
    response_started_at_ms:
      input.response_started_at_ms,
    response_prompt: responsePrompt,
  },
}];

const envelope = $json ?? {};
let parsed = envelope.output ?? envelope;

if (typeof parsed === 'string') {
  try {
    parsed = JSON.parse(parsed);
  } catch {
    const match = parsed.match(/\{[\s\S]*\}/);
    if (!match) {
      throw new Error('AI response is not valid JSON.');
    }
    parsed = JSON.parse(match[0]);
  }
}

if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.output &&
  typeof parsed.output === 'object'
) {
  parsed = parsed.output;
}

const context = $('Prepare Response Composition Context').first().json;
const source = context.response_context || {};
const safety = source.safety_payload || {};
const routing = source.routing_payload || {};
const execution = source.execution_payload || {};
const aiRoute = source.ai_route_output || {};

const routeStatus = String(
  routing.route_status || ''
).trim();

const executionExists =
  execution &&
  typeof execution === 'object' &&
  Object.keys(execution).length > 0;

const executionSucceeded =
  executionExists &&
  execution.success === true;

const executionFailed =
  executionExists &&
  execution.success === false;

let responseText = String(
  parsed.response_text || ''
).trim();

if (
  safety.safety_decision === 'urgent_handoff' &&
  context.deterministic_instruction
) {
  responseText = String(
    context.deterministic_instruction
  ).trim();
}

if (!responseText) {
  responseText =
    context.deterministic_instruction ||
    'درخواست شما دریافت شد.';
}

const language =
  parsed.language ||
  source.language ||
  'unknown';

let responseType =
  parsed.response_type || 'answer';

let conversationStatus =
  parsed.conversation_status || 'active';

let requiresHumanReview =
  Boolean(parsed.requires_human_review);

if (
  safety.safety_decision === 'urgent_handoff'
) {
  responseType = 'urgent_safety_message';
  conversationStatus = 'waiting_human';
  requiresHumanReview = true;
}

if (
  [
    'human_handoff',
    'allow_with_human_review',
  ].includes(safety.safety_decision)
) {
  responseType =
    responseType === 'urgent_safety_message'
      ? responseType
      : 'human_handoff_acknowledgement';
  conversationStatus = 'waiting_human';
  requiresHumanReview = true;
}

if (
  [
    'needs_input',
    'patient_input_required',
  ].includes(routeStatus)
) {
  responseType =
    routeStatus === 'patient_input_required'
      ? 'confirmation_request'
      : 'missing_information_question';
  conversationStatus = 'waiting_patient';

  if (!responseText) {
    responseText = String(
      aiRoute.next_question ||
      'برای ادامه، لطفاً اطلاعات خواسته‌شده را ارسال کنید.'
    ).trim();
  }
}

if (routeStatus === 'unsupported_tool') {
  responseType = 'human_handoff_acknowledgement';
  conversationStatus = 'waiting_human';
  requiresHumanReview = true;

  if (!responseText) {
    responseText =
      'درخواست شما برای بررسی به اپراتور انسانی ارجاع شد.';
  }
}

if (executionSucceeded) {
  responseType = 'completed_action_result';

  if (
    conversationStatus !== 'waiting_human' &&
    conversationStatus !== 'waiting_patient'
  ) {
    conversationStatus = 'active';
  }
}

if (executionFailed) {
  responseType = 'error_message';
  conversationStatus = 'waiting_human';
  requiresHumanReview = true;

  if (!responseText) {
    responseText =
      'در اجرای درخواست مشکلی رخ داد. موضوع برای بررسی انسانی ثبت شد.';
  }
}

return [{
  json: {
    success: true,
    result: 'patient_response_composed',
    session_id: Number(source.session_id),
    input_message_id: Number(source.message_id),
    language,
    response_type: responseType,
    response_text: responseText.slice(0, 2000),
    should_send:
      parsed.should_send !== false,
    requires_human_review:
      requiresHumanReview,
    conversation_status: conversationStatus,
    reason_summary: String(
      parsed.reason_summary || ''
    ).slice(0, 500),
    model_provider: context.model_provider,
    model_name: context.model_name,
    prompt_version: context.prompt_version,
    raw_output_json: JSON.stringify(envelope),
    latency_ms: Math.max(
      0,
      Date.now() -
        Number(
          context.response_started_at_ms ||
          Date.now()
        )
    ),
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات لازم برای ساخت پاسخ ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];

return [{
  json: {
    success: false,
    result: $json.result || 'response_context_not_available',
    message:
      $json.result === 'safety_decision_not_found'
        ? 'ابتدا Workflow شماره 52 را برای این پیام اجرا کنید.'
        : 'پیام یا جلسه مکالمه پیدا نشد.',
  },
}];
